INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3059099, 428810, 66201, '<td valign="top">Duckie''s been done now. Too much dead space in the middle, background OOF and not saying much about the topic, and the subject not looking as if he''s run a marathon...?</td>', 'Duckie''s been done now. Too much dead space in the middle, background OOF and not saying much about the topic, and the subject not looking as if he''s run a marathon...?', '2006-11-24 07:31:19.000000', NULL, 1),
(3059101, 430463, 66201, '<td valign="top">10! Well done for your Candid Bravery... This is hysterical. Excellent interpretation of the topic.</td>', '10! Well done for your Candid Bravery... This is hysterical. Excellent interpretation of the topic.', '2006-11-24 07:31:41.000000', NULL, 1),
(3059102, 430427, 66201, '<td valign="top">Oh just perfect. Love it...excellent recreation of the album cover. 9</td>', 'Oh just perfect. Love it...excellent recreation of the album cover. 9', '2006-11-24 07:31:49.000000', NULL, 1),
(3059103, 430453, 66201, '<td valign="top">This is a great composition and idea...well done 9</td>', 'This is a great composition and idea...well done 9', '2006-11-24 07:32:00.000000', NULL, 1),
(3059105, 429543, 66201, '<td valign="top">Well done: great nostalgia and sense of things past. Love it. 9</td>', 'Well done: great nostalgia and sense of things past. Love it. 9', '2006-11-24 07:32:13.000000', NULL, 1),
(3059106, 429494, 66201, '<td valign="top">Excellent: how funny!! I remember this look and phase so well...Great interpretation</td>', 'Excellent: how funny!! I remember this look and phase so well...Great interpretation', '2006-11-24 07:32:26.000000', NULL, 1),
(3059108, 430020, 66201, '<td valign="top">I love the colours that come through in this simple, yet effective image.</td>', 'I love the colours that come through in this simple, yet effective image.', '2006-11-24 07:32:42.000000', NULL, 1),
(3059109, 430467, 66201, '<td valign="top">Very effective: a great close-up that maintains the subject. Love the black, white, green contrasts.</td>', 'Very effective: a great close-up that maintains the subject. Love the black, white, green contrasts.', '2006-11-24 07:32:50.000000', NULL, 1),
(3059110, 430369, 66201, '<td valign="top">Excellent set up. What a great choice of topic. Well done.</td>', 'Excellent set up. What a great choice of topic. Well done.', '2006-11-24 07:32:55.000000', NULL, 1),
(3059111, 430379, 66201, '<td valign="top">Fantastic choice of subject for the year. Well done.</td>', 'Fantastic choice of subject for the year. Well done.', '2006-11-24 07:33:02.000000', NULL, 1),
(3059112, 427763, 66201, '<td valign="top">Very evocative...I like the overcast lighting.</td>', 'Very evocative...I like the overcast lighting.', '2006-11-24 07:33:07.000000', NULL, 1),
(3059113, 430358, 66201, '<td valign="top">Nice crop. The b+w works well.</td>', 'Nice crop. The b+w works well.', '2006-11-24 07:33:14.000000', NULL, 1),
(3059114, 430252, 66201, '<td valign="top">Great composition and subject(s). Maybe could have done with some post-processing: warmer tones?</td>', 'Great composition and subject(s). Maybe could have done with some post-processing: warmer tones?', '2006-11-24 07:33:21.000000', NULL, 1),
(3059115, 428514, 66201, '<td valign="top">What fun: nice brightness and I like the soft focus.</td>', 'What fun: nice brightness and I like the soft focus.', '2006-11-24 07:33:25.000000', NULL, 1),
(3059116, 430428, 66201, '<td valign="top">very stylish</td>', 'very stylish', '2006-11-24 07:33:30.000000', NULL, 1),
(3059117, 429922, 66201, '<td valign="top">Witty... find the dark side of the apple a bit too dominant...either would have liked to see the brightness and greenness of the whole apple, or a stark contrast between bright green and shadow, without seeing background...if that makes any sense?</td>', 'Witty... find the dark side of the apple a bit too dominant...either would have liked to see the brightness and greenness of the whole apple, or a stark contrast between bright green and shadow, without seeing background...if that makes any sense?', '2006-11-24 07:33:36.000000', NULL, 1),
(3059119, 430013, 66201, '<td valign="top">I like the image, but not sure it speaks much about the book?</td>', 'I like the image, but not sure it speaks much about the book?', '2006-11-24 07:33:43.000000', NULL, 1),
(3059120, 430300, 66201, '<td valign="top">Arrgh...cringe...yes I remember the look. Well done.</td>', 'Arrgh...cringe...yes I remember the look. Well done.', '2006-11-24 07:33:52.000000', NULL, 1),
(3059124, 430292, 66201, '<td valign="top">Oh yes...remember that... I was sporting a pair of those and listening to the soundtrack of "Ghostbusters" once upon a time! Lovely hues and tones</td>', 'Oh yes...remember that... I was sporting a pair of those and listening to the soundtrack of "Ghostbusters" once upon a time! Lovely hues and tones', '2006-11-24 07:35:44.000000', NULL, 1),
(3059125, 429963, 66201, '<td valign="top">okay this has to be B74A''s shot...? Can it be that the boeing only came into being in my lifetime?? Amazing.</td>', 'okay this has to be B74A''s shot...? Can it be that the boeing only came into being in my lifetime?? Amazing.', '2006-11-24 07:35:53.000000', NULL, 1),
(3059126, 429830, 66201, '<td valign="top">Weird effect: I was in high school when this movie came out...now my children are watching it in it''s re-edited state...</td>', 'Weird effect: I was in high school when this movie came out...now my children are watching it in it''s re-edited state...', '2006-11-24 07:36:47.000000', NULL, 1),
(3059128, 430362, 66201, '<td valign="top">well how about that!? Great example from your year.</td>', 'well how about that!? Great example from your year.', '2006-11-24 07:37:03.000000', NULL, 1),
(3059130, 430305, 66201, '<td valign="top">...could have entered this for the "famous last words" challenge too! Lol... Nice idea and works well in B + W. Maybe a tighter crop at the top?</td>', '...could have entered this for the "famous last words" challenge too! Lol... Nice idea and works well in B + W. Maybe a tighter crop at the top?', '2006-11-24 07:38:09.000000', NULL, 1),
(3059132, 428201, 66201, '<td valign="top">Powerful topic to select: phew. Love the colours and the selected graphics...just me, but I would have liked some humanness in this..a child staring up at the images, or an old person in it...? We have a slab of the wall in our neck of the woods too..it doesn''t have as much spray paint on it.</td>', 'Powerful topic to select: phew. Love the colours and the selected graphics...just me, but I would have liked some humanness in this..a child staring up at the images, or an old person in it...? We have a slab of the wall in our neck of the woods too..it doesn''t have as much spray paint on it.', '2006-11-24 07:39:51.000000', NULL, 1),
(3059133, 430274, 66201, '<td valign="top">Simple and yet somehow evokes a ''60''s feel. We had so many B + W photos in the house when I grew up. Wonder if the young ''uns will appreciate this when voting?</td>', 'Simple and yet somehow evokes a ''60''s feel. We had so many B + W photos in the house when I grew up. Wonder if the young ''uns will appreciate this when voting?', '2006-11-24 07:41:01.000000', NULL, 1),
(3059134, 429986, 66201, '<td valign="top">Oh excellent choice and such a witty angle and composition.</td>', 'Oh excellent choice and such a witty angle and composition.', '2006-11-24 07:41:07.000000', NULL, 1),
(3059135, 430331, 66201, '<td valign="top">very eye-catching and a great find in terms of subject idea.</td>', 'very eye-catching and a great find in terms of subject idea.', '2006-11-24 07:41:12.000000', NULL, 1),
(3059136, 429946, 66201, '<td valign="top">Really natty... well done</td>', 'Really natty... well done', '2006-11-24 07:41:19.000000', NULL, 1),
(3059137, 429481, 66201, '<td valign="top">Fan of Dylan and I like this image too!</td>', 'Fan of Dylan and I like this image too!', '2006-11-24 07:41:40.000000', NULL, 1),
(3059138, 429681, 66201, '<td valign="top">expertly set up and I like the B + W option. Nice clarity and crop.</td>', 'expertly set up and I like the B + W option. Nice clarity and crop.', '2006-11-24 07:41:47.000000', NULL, 1),
(3059139, 429991, 66201, '<td valign="top">Fantastic idea: love it!</td>', 'Fantastic idea: love it!', '2006-11-24 07:41:54.000000', NULL, 1),
(3059140, 428181, 66201, '<td valign="top">Very emotive and lovely detail and set-up.</td>', 'Very emotive and lovely detail and set-up.', '2006-11-24 07:42:26.000000', NULL, 1),
(3059144, 427844, 66201, '<td valign="top">simple, and yet effective.</td>', 'simple, and yet effective.', '2006-11-24 07:43:34.000000', NULL, 1),
(3059145, 430403, 66201, '<td valign="top">Ah terrific example...My year too!!:) Can''t believe that 20 years later we were made to do a film study of this at ''varsity.  The only person in the lecture hall to get excited about the movie was the aged hippie lecturer!! Lol.</td>', 'Ah terrific example...My year too!!:) Can''t believe that 20 years later we were made to do a film study of this at ''varsity.  The only person in the lecture hall to get excited about the movie was the aged hippie lecturer!! Lol.', '2006-11-24 07:43:42.000000', NULL, 1),
(3059148, 430386, 66201, '<td valign="top">The background is distracting...ie. where the sheet ends. Would have liked more atmosphere in this...less bright and light. Maybe if the light was one-directional and the figure was in half shadow..? dunno.</td>', 'The background is distracting...ie. where the sheet ends. Would have liked more atmosphere in this...less bright and light. Maybe if the light was one-directional and the figure was in half shadow..? dunno.', '2006-11-24 07:45:07.000000', NULL, 1),
(3059151, 430380, 66201, '<td valign="top">The border makes a potentially un-exiting photo, a crisp and stylish work.</td>', 'The border makes a potentially un-exiting photo, a crisp and stylish work.', '2006-11-24 07:45:48.000000', NULL, 1),
(3059157, 429159, 66201, '<td valign="top">Lovely..but you may find that you get criticised for not having included your year in the title...?</td>', 'Lovely..but you may find that you get criticised for not having included your year in the title...?', '2006-11-24 07:47:31.000000', NULL, 1),
(3059170, 429972, 66201, '<td valign="top">Seems OOF, but apart from that, this is such a well-known, obvious graphic, that you needed to have been bolder in using it, or more technical in creating a crisp image...it bothers me that the tips of the ribbon are not centred.</td>', 'Seems OOF, but apart from that, this is such a well-known, obvious graphic, that you needed to have been bolder in using it, or more technical in creating a crisp image...it bothers me that the tips of the ribbon are not centred.', '2006-11-24 07:51:49.000000', NULL, 1),
(3059207, 430046, 67001, '<td valign="top">No mention of the year in the title...<br/> <br/>It is hard for people (without seeing the article first) to know what some of these photos mean. I am sorry if I did not "clue in" that what you wanted to show was a nuclear explosion test...<br/> <br/>As far as the photo, I really like the way you cropped it. On the other hand I see a few flaws... The background distracts from your subject. The lighting is harsh in many places. There is excessive shadows around the mouth area. Maybe using a reflector on the right side of Buddha at a 45 degree angle would do him some good.<br/> <br/>I hiope this helps... Good luck!</td>', 'No mention of the year in the title... It is hard for people (without seeing the article first) to know what some of these photos mean. I am sorry if I did not "clue in" that what you wanted to show was a nuclear explosion test... As far as the photo, I really like the way you cropped it. On the other hand I see a few flaws... The background distracts from your subject. The lighting is harsh in many places. There is excessive shadows around the mouth area. Maybe using a reflector on the right side of Buddha at a 45 degree angle would do him some good. I hiope this helps... Good luck!', '2006-11-24 08:21:07.000000', NULL, 1),
(3059209, 428427, 67001, '<td valign="top">Was this shot on a hill or you tripped? :-) Sorry, the horizon is very crooked and distracting... Was this intentional?<br/> <br/>Good luck.</td>', 'Was this shot on a hill or you tripped? :-) Sorry, the horizon is very crooked and distracting... Was this intentional? Good luck.', '2006-11-24 08:22:27.000000', NULL, 1),
