(3070497, 429533, 60505, '<td valign="top">Sorry you didnt get in the top 10. Definitely on of my all time DPC photos. My daughter is visiting J''burg next week, and have a few friends from there too. You are right. Not enough people appreciate the real beauty in this photo.</td>', 'Sorry you didnt get in the top 10. Definitely on of my all time DPC photos. My daughter is visiting J''burg next week, and have a few friends from there too. You are right. Not enough people appreciate the real beauty in this photo.', '2006-11-29 02:03:37.000000', NULL, 0),
(3070503, 428181, 57202, '<td valign="top">This is still one of my favorite photos of the challenge by far. :)  The gritty quality, the colors, and the attention to detail is spectacular.  Congrats on the awesome finish!</td>', 'This is still one of my favorite photos of the challenge by far. :)  The gritty quality, the colors, and the attention to detail is spectacular.  Congrats on the awesome finish!', '2006-11-29 02:06:54.000000', NULL, 0),
